entries[194509] = { ["name"] = "Springborn Core", ["text"] = "Quest Item\n\"A powerful elemental core formed within the waters of a hotspring.\"" }
entries[194510] = { ["name"] = "Iskaaran Harpoon", ["text"] = "Use: Face a \"Lunker\", then throw! (4 Sec Cooldown)" }
entries[194511] = { ["name"] = "Living Ration", ["text"] = "Binds when picked up\nUnique" }
entries[194512] = { ["name"] = "Broken Arcane Device", ["text"] = "Quest Item\n\"Some arcane magic still sparks out of this piece of the device.\"" }
entries[194513] = { ["name"] = "Collection of Tomes", ["text"] = "Quest Item\n\"These tomes detail the history of what Camp Antonidas once was 10,000 years ago.\"" }
entries[194514] = { ["name"] = "Antiquated Guest List", ["text"] = "Quest Item\n\"This old tome has the names of dragons who frequented this area. Two names are on almost every page: Malygos and Sindragosa.\"" }
entries[194515] = { ["name"] = "Crumbling Event Planner", ["text"] = "Quest Item\n\"This book details various events that were held in this area. All of them seemed to involve displays of arcana to show other dragonflights and aspects.\"" }
entries[194516] = { ["name"] = "Aged Journal", ["text"] = "Quest Item\n\"These pages have details about the courtship between two blue dragons, Malygos and Sindragosa. One note indicates this is, \"part one of a series\".\"" }
entries[194517] = { ["name"] = "Broken Texts", ["text"] = "Quest Item\n\"This book details the drakonid and dragonspawn that looked after this area after the blue dragons left. Many pages lament about the \"cheer\" being gone with the absence of Sindragosa and Malygos.\"" }
entries[194519] = { ["name"] = "Osoria's Assistance", ["text"] = "Quest Item\nUse: Call upon Osoria to carry you into the air and engage enemies. Only within the Obsidian Citadel. (5 Sec Cooldown)\nRequires level 10 to 70 ( 70)" }
entries[194520] = { ["name"] = "Scroll of Timewalker Knowledge", ["text"] = "Quest Item\n\"The scroll contains a wealth of knowledge about time magic. You feel your mind bending if you stare at the parchment too long.\"" }
entries[194521] = { ["name"] = "Cliffside Wylderdrake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Often roosting along the steep cliff faces of Thaldraszus, they're swift to the skies in times of danger.\"\nAchievement:\nDragon Isles: Cliffside Wylderdrake" }
